// Bounded, geometry-cached land routing is only a spawn-location screening metric.
let basinGraphWeb=null;const basinPathsWeb=new Map();
function basinPathGridWeb(){if(basinGraphWeb)return basinGraphWeb;let b=mapSpec.bounds,step=20,nx=Math.round((b.xmax-b.xmin)/step)+1,ny=Math.round((b.ymax-b.ymin)/step)+1,pass=new Uint8Array(nx*ny),boxes=mountainPolygons.map(p=>({p,x0:Math.min(...p.map(q=>q.x)),x1:Math.max(...p.map(q=>q.x)),y0:Math.min(...p.map(q=>q.y)),y1:Math.max(...p.map(q=>q.y))}));function mountain(p){return boxes.some(r=>p.x>=r.x0&&p.x<=r.x1&&p.y>=r.y0&&p.y<=r.y1&&pointInPolygon(p,r.p));}for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){let p={x:b.xmin+x*step,y:b.ymin+y*step};pass[y*nx+x]=inRiverValley(p)||[p,{x:p.x-7,y:p.y},{x:p.x+7,y:p.y},{x:p.x,y:p.y-7},{x:p.x,y:p.y+7}].every(q=>!mountain(q))?1:0;}return basinGraphWeb={b,step,nx,ny,pass};}
function basinRouteDistancesWeb(city){let key=city.x+','+city.y;if(basinPathsWeb.has(key))return basinPathsWeb.get(key);let g=basinPathGridWeb(),{b,step,nx,ny,pass}=g,dist=new Float64Array(nx*ny);dist.fill(Infinity);let ix=Math.round((city.x-b.xmin)/step),iy=Math.round((city.y-b.ymin)/step),start=iy*nx+ix;if(!pass[start]){let best=Infinity;for(let k=0;k<pass.length;k++)if(pass[k]){let d=Math.hypot(k%nx-ix,Math.floor(k/nx)-iy);if(d<best){best=d;start=k;}}}let heap=[];function push(i,d){let n=heap.length;heap.push([i,d]);while(n){let p=(n-1)>>1;if(heap[p][1]<=d)break;heap[n]=heap[p];n=p;}heap[n]=[i,d];}function pop(){let root=heap[0],last=heap.pop();if(heap.length){let i=0;while(i*2+1<heap.length){let j=i*2+1;if(j+1<heap.length&&heap[j+1][1]<heap[j][1])j++;if(heap[j][1]>=last[1])break;heap[i]=heap[j];i=j;}heap[i]=last;}return root;}dist[start]=0;push(start,0);while(heap.length){let [u,d]=pop();if(d!==dist[u])continue;let x=u%nx,y=Math.floor(u/nx);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;let xx=x+dx,yy=y+dy;if(xx<0||xx>=nx||yy<0||yy>=ny)continue;let v=yy*nx+xx;if(!pass[v]||dx&&dy&&(!pass[y*nx+xx]||!pass[yy*nx+x]))continue;let nd=d+step*(dx&&dy?Math.SQRT2:1);if(nd<dist[v]){dist[v]=nd;push(v,nd);}}}basinPathsWeb.set(key,dist);if(basinPathsWeb.size>64)basinPathsWeb.delete(basinPathsWeb.keys().next().value);return dist;}
function basinSpawnAllowedWeb(p){if(mapSpec.id!=='west')return true;let cap=S.day<65?2400:S.day<120?4200:6500,ratio=S.day<65?1.8:S.day<120?2.3:3,g=null;for(let c of realCities().filter(c=>!c.removed)){let eu=Math.hypot(c.x-p.x,c.y-p.y);if(!eu)continue;let req=requirements(c,p,'bus'),cost=10*Math.ceil(eu*.38)+req.bridge*1500+req.tunnel*2200;if(cost>cap)continue;if(!req.tunnel)return true;g??=basinPathGridWeb();let x=Math.round((p.x-g.b.xmin)/g.step),y=Math.round((p.y-g.b.ymin)/g.step),d=basinRouteDistancesWeb(c)[y*g.nx+x];if(d/eu<=ratio)return true;}return false;}
const localBeforeBasinWeb=localAllowed;
localAllowed=function(p,r,options){return localBeforeBasinWeb(p,r,options)&&basinSpawnAllowedWeb(p);};
const seedPreviewBeforeBasinWeb=previewSeedCluster;
previewSeedCluster=function(p){if(mapSpec.id!=='west')return seedPreviewBeforeBasinWeb(p);let centers=cityRegions(),preview=[p],directions=new Set(),choices=growthAvailable.filter(q=>Math.hypot(q.x-p.x,q.y-p.y)<=520&&farEnough(q,p)&&!reservedForOther(q,-1)&&realCities().every(c=>c.removed||Math.hypot(q.x-c.x,q.y-c.y)>=320)&&centers.every(r=>Math.hypot(q.x-r.x,q.y-r.y)>=Math.hypot(q.x-p.x,q.y-p.y)+100));for(let i=1;i<8;i++){let eligible=choices.filter(q=>preview.some(c=>{let d=Math.hypot(q.x-c.x,q.y-c.y);return d>=195&&d<=330;}));if(!eligible.length)break;let dir=q=>(q.x>=p.x?1:0)+(q.y>=p.y?2:0);eligible.sort((a,b)=>((directions.has(dir(a))?1000:0)+Math.abs(Math.hypot(a.x-p.x,a.y-p.y)-230))-((directions.has(dir(b))?1000:0)+Math.abs(Math.hypot(b.x-p.x,b.y-p.y)-230)));let q=eligible[0];preview.push(q);directions.add(dir(q));choices=choices.filter(x=>farEnough(x,q));}return preview.length>=5&&directions.size>=2?preview:null;};
const localFindBeforeBasinWeb=findLocal;
findLocal=function(r){if(mapSpec.id!=='west')return localFindBeforeBasinWeb(r);let reserved=(r.reservedPoints||[]).filter(p=>growthAvailable.some(q=>q.x===p.x&&q.y===p.y)&&localAllowed(p,r));if(reserved.length)return pick(reserved);let choices=growthAvailable.filter(p=>localAllowed(p,r));
// A valid fourth town can close the small 330-unit pool. Search nearby same-circle land
// before waiting for a later cost tier; spacing, cost and other-circle guards still apply.
if(!choices.length&&r.id===0){
 for(let options of [{maxLink:460,radius:Math.min(760,growthRadius(r)+160)},{maxLink:600,radius:760}]){
  choices=growthAvailable.filter(p=>localAllowed(p,r,options));if(choices.length){let near=p=>Math.min(...clusterMembers(r).map(c=>Math.hypot(c.x-p.x,c.y-p.y)));choices.sort((a,b)=>near(a)-near(b));choices=choices.filter(p=>near(p)<=near(choices[0])+40);break;}
 }
}
return choices.length?pick(choices):null;};
const seedFindBeforeBasinWeb=findSeed;
findSeed=function(first=false){if(mapSpec.id!=='west')return seedFindBeforeBasinWeb(first);let choices=growthAvailable.filter(p=>{if(!basinSpawnAllowedWeb(p)||reservedForOther(p,-1))return false;let near=Math.min(...realCities().filter(c=>!c.removed).map(c=>Math.hypot(c.x-p.x,c.y-p.y)));if(near<420||near>700)return false;return first?cityRegions().some(r=>{let d=Math.hypot(p.x-r.x,p.y-r.y);return d>=590&&d<=760;}):cityRegions().every(r=>Math.hypot(p.x-r.x,p.y-r.y)>=1000);});while(choices.length){let i=Math.floor(Math.random()*choices.length),p=choices.splice(i,1)[0],plan=previewSeedCluster(p);if(plan){pendingSeedPlan=plan;return p;}}return null;};
const outlyingBeforeBasinWeb=findOutlier;
findOutlier=function(){if(mapSpec.id!=='west')return outlyingBeforeBasinWeb();let old=growthAvailable;try{for(let i=0;i<20;i++){let p=outlyingBeforeBasinWeb();if(!p)return null;if(basinSpawnAllowedWeb(p))return p;growthAvailable=growthAvailable.filter(q=>q!==p);}return null;}finally{growthAvailable=old;}};
const maturityBeforeBasinWeb=updateGrowthMaturity;
updateGrowthMaturity=function(){if(mapSpec.id!=='west')return maturityBeforeBasinWeb();let gs=growthState(),r=cityRegions().find(r=>r.id===gs.focus);if(!r||gs.readyAt!==null||r.id===0)return;let n=clusterMembers(r,true).length;if(S.day-r.discoveredAt<90||n<5||growthDirections(r).size<2)return;let noRoom=n<6&&!growthAvailable.some(p=>localAllowed(p,r));if(n>=6||noRoom){gs.readyAt=S.day+25;gs.maturity.push({id:r.id,day:S.day,readyAt:gs.readyAt,open:n,directions:growthDirections(r).size});}};
